def solution(input_str):
    l, r = map(int, input_str.strip().split())

    if l > r:
        return '0\n'

    # Compute limit for sieving
    limit = int(r ** 0.5) + 1
    small_primes = []

    # Sieve of Eratosthenes up to sqrt(r)
    is_prime_small = [True] * (limit + 1)
    is_prime_small[0] = is_prime_small[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime_small[i]:
            for j in range(i * i, limit + 1, i):
                is_prime_small[j] = False

    for i in range(2, limit + 1):
        if is_prime_small[i]:
            small_primes.append(i)

    # Segmented sieve for [l, r]
    size = r - l + 1
    is_prime_range = [True] * size

    # Handle l = 1 case
    if l == 1:
        is_prime_range[0] = False

    for p in small_primes:
        # Find the first multiple of p in [l, r]
        start = max(p * p, ((l + p - 1) // p) * p)
        for j in range(start, r + 1, p):
            is_prime_range[j - l] = False

    # Count primes that are either 2 or ≡ 1 (mod 4)
    count = 0
    for i in range(size):
        if is_prime_range[i]:
            num = l + i
            if num == 2 or num % 4 == 1:
                count += 1

    return f'{count}\n'
