            if self.pos < len(self.s):
                return self.s[self.pos]
            return None

        def consume(self):
            if self.pos < len(self.s):
                ch = self.s[self.pos]
                self.pos += 1
                return ch
            return None

        def parse_number(self):
            start = self.pos
            while self.pos < len(self.s) and self.s[self.pos].isdigit():
                self.pos += 1
            return int(self.s[start:self.pos])

        def parse_term(self):
            if self.peek() == '(' or self.peek() is None:
                return int('')

            # Parse the number at start of term
            base_num = self.parse_number()

            # Check what follows
            ch = self.peek()

            if ch == '-':
                self.consume()  # consume '-'
                num2 = self.parse_number()
                if num2 < base_num:
                    raise ValueError(f"Range invalid: {base_num}-{num2}, need base_num >= num2")
