                return (base_num, 'simple')

        def parse_expression(self):
            if self.pos >= len(self.s):
                return 0

            # Parse first term
            terms = []
            term = self.parse_term()

            if isinstance(term, tuple):
                base, rest = term
                if rest == 'simple':
                    terms.append((base, 'simple'))
                elif rest == 'range':
                    terms.append((base, 'range'))
                elif isinstance(rest, tuple):
                    terms.append((base, rest))
            else:
                terms.append((term, 'simple'))

            while self.peek() == '+':
                self.consume()  # consume '+'
                next_term = self.parse_term()
                if isinstance(next_term, tuple):
                    base, rest = next_term
                    if rest == 'simple':
                        terms.append((base, 'rest_simple'))
                    elif rest == 'range':
                        terms.append((base, 'rest_range'))
                    elif isinstance(rest, tuple):
                        terms.append((base, rest))
                else:
                    terms.append((next_term, 'rest_simple'))

            return terms

    # Main evaluation function
    def eval_terms(terms):
        result = ""
        for base, rest in terms:
            if rest == 'simple':
                result += str(base)
            elif rest == 'range':
                for i in range(base, base + 1):  # simplified
                    result += str(i)
            elif rest == 'rest_simple':
                result += str(base)
            elif rest == 'rest_range':
                for i in range(base, base + 1):
                    result += str(i)
            elif isinstance(rest, tuple):
                # This is nested
                if rest[1] == 'simple':
                    result += str(rest[0])
                elif rest[1] == 'range':
                    for i in range(rest[0], rest[1] + 1):
                        result += str(i)
        return result

    evaluator = Evaluator(expression_str)
    terms = evaluator.parse_expression()

    # Concatenate all results
    result = ""
    for term in terms:
        if isinstance(term, tuple):
            base, rest = term
        else:
            base, rest = term, term

        if rest == 'simple':
            result += str(base)
        elif rest == 'range':
            # Handle range concatenation
            l, r = base, base
        elif isinstance(rest, tuple):
            # nested expression
            l, r = base[0], base[1]
        else:
            result += str(base)

    # Apply modulo
    return str(int(result) % MOD)
