# solution.py
class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 1))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union_range(self, l, r):
        """Union all days in [l, r] into one component."""
        if l > r:
            return
        for i in range(l + 1, r + 1):
            self.union(self.find(l), i)

    def find_set(self, x):
        return self.find(x)

def solve():
    data = input_str.strip().split('\n')
    if not data:
        return ''

    n, m = map(int, data[0].split())
    offers = []
    for i in range(1, m + 1):
        if i <= len(data):
            l, r = map(int, data[i].split())
            offers.append((l, r))

    results = []

    for x in range(1, n + 1):
        uf = UnionFind(n)
        occupied = [False] * (n + 2)
        total_days = 0

        for l, r in offers:
            if r - l + 1 >= x:
                range_empty = True
                for day in range(l, r + 1):
                    if not occupied[day]:
                        continued = True
                        # Check if this day is already in an occupied range
                        if uf.find_set(l) == uf.find_set(day):
                            range_empty = False
                            break
                    else:
                        range_empty = False
                        break

                if range_empty:
                    for day in range(l, r + 1):
                        occupied[day] = True
                        uf.union_range(l, r)
                    total_days += r - l + 1

        results.append(str(total_days))

    print('\n'.join(results))
    return '\n'.join(results)

if __name__ == "__main__":
    input_str = sys.stdin.read()
    solve()
