class FenwickTree:
    def __init__(self, size):
        self.tree = [0] * (size + 2)

    def update(self, i, val):
        i += 1
        while i < len(self.tree):
            self.tree[i] = max(self.tree[i], val)
            i += i & (-i)

    def query(self, i):
        i += 1
        res = 0
        while i > 0:
            res = max(res, self.tree[i])
            i -= i & (-i)
        return res

